const LANGS = ['en', 'fr', 'es', 'it', 'nl', 'de', 'ar', 'hi', 'zh', 'tr', 'ru'];

function toDartString(str) {
  const escaped = str
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\$/g, '\\$');
  return `'${escaped}'`;
}

function validateEntries() {
  const seen = new Set();
  for (const entry of entries) {
    if (seen.has(entry.key)) {
      throw new Error(`Duplicate key in entries array: ${entry.key}`);
    }
    seen.add(entry.key);
    for (const lang of LANGS) {
      if (typeof entry[lang] !== 'string' || entry[lang].length === 0) {
        throw new Error(`Missing/empty translation for key "${entry.key}" in language "${lang}"`);
      }
    }
  }
  return seen.size;
}

function injectAll() {
  const totalKeys = validateEntries();
  const filePath = path.join(__dirname, '..', 'lib', 'l10n', 'string_tables_extra.dart');
  let content = fs.readFileSync(filePath, 'utf8');

  for (const lang of LANGS) {
    const varName = `_${lang}Extra`;
    const startMarker = `const Map<String, String> ${varName} = {`;
    const startIdx = content.indexOf(startMarker);
    if (startIdx === -1) {
      throw new Error(`Could not find block start for ${varName}`);
    }
    const blockBodyStart = startIdx + startMarker.length;
    const endIdx = content.indexOf('\n};', blockBodyStart);
    if (endIdx === -1) {
      throw new Error(`Could not find block end for ${varName}`);
    }

    const blockContent = content.slice(blockBodyStart, endIdx);
    const existingKeys = new Set();
    const keyRegex = /^\s*'([^'\\]+)':/gm;
    let m;
    while ((m = keyRegex.exec(blockContent)) !== null) {
      existingKeys.add(m[1]);
    }

    const lines = entries.map((entry) => {
      if (existingKeys.has(entry.key)) {
        throw new Error(`Key "${entry.key}" already exists in ${varName} block`);
      }
      return `  ${toDartString(entry.key)}: ${toDartString(entry[lang])},`;
    });

    const insertion = '\n' + lines.join('\n');
    content = content.slice(0, endIdx) + insertion + content.slice(endIdx);
  }

  fs.writeFileSync(filePath, content, 'utf8');
  console.log(
    `Injected ${totalKeys} keys x ${LANGS.length} languages = ${totalKeys * LANGS.length} strings into ${filePath}`
  );
}

if (require.main === module) {
  injectAll();
}

module.exports = { entries, toDartString, injectAll };
